window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a4ee3b1d3977bf8a"]={"versions": [{"id": "FIG-a4ee3b1d3977bf8a", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsübersicht mit drei isolierten Zustandswechsel-Szenarien).</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert die BSW-Interaktion auf System-Service-Ebene zwischen dem Communication Manager (<code>ComM</code>) und dem Diagnostic Communication Manager (<code>Dcm</code>) gemäß AUTOSAR Classic Platform (SWS DCM, Release R24-11).</li>\n<li><strong>Technischer Zweck:</strong> Kanalbezogene Steuerung der diagnostischen Sende- und Empfangsbereitschaft des Dcm (Diagnostic Session Layer / DSL) in Abhängigkeit vom Netzwerkmodus des jeweiligen Kommunikationskanals (Verhinderung unzulässiger Buslast oder unerwünschten Bus-Wakeups).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Module (Akteure):</strong></li>\n<li><code>«module» ComM</code>: Koordinator der Buskommunikationszustände (Network Management / State Machine).</li>\n<li><code>«module» Dcm</code>: Protokoll- und Session-Handler für UDS/OBD-Diagnose.</li>\n<li><strong>Dcm Mode-Notification APIs (Aufruf durch ComM):</strong></li>\n<li><code>Dcm_ComM_NoComModeEntered(uint8 NetworkId)</code>: Signalisiert Kanal-Übergang zu <code>COMM_NO_COMMUNICATION</code>.</li>\n<li><code>Dcm_ComM_SilentComModeEntered(uint8 NetworkId)</code>: Signalisiert Kanal-Übergang zu <code>COMM_SILENT_COMMUNICATION</code>.</li>\n<li><code>Dcm_ComM_FullComModeEntered(uint8 NetworkId)</code>: Signalisiert Kanal-Übergang zu <code>COMM_FULL_COMMUNICATION</code>.</li>\n<li><strong>Interne / Unterlagerte Schnittstellen:</strong></li>\n<li><code>PduR_DcmTransmit()</code>: PDU-Router-Schnittstelle zur Übertragung diagnostischer Antworten.</li>\n<li>ROE-Handler (UDS 0x86 <em>ResponseOnEvent</em>) und Periodic-ID-Handler (UDS 0x2A <em>ReadDataByPeriodicIdentifier</em>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. No Communication State (<code>COMM_NO_COMMUNICATION</code>)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>ComM</code> ruft synchron <code>Dcm_ComM_NoComModeEntered(uint8 NetworkId)</code> auf.</li>\n<li><strong>Aktionen im Dcm:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Deaktivierung der Transmission für ROE und Periodic-IDs auf dem betroffenen Netzwerk.</li>\n<li>Vollständiges Sperren der normalen Diagnose-Kommunikation: Empfang (<code>Rx</code>) und Senden (<code>Tx</code> via <code>PduR_DcmTransmit()</code>) werden unterbunden.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Synchroner Rücksprung (<code>Dcm_ComMNoComModeEntered()</code>) an <code>ComM</code>.</li>\n</ol>\n<p class=\"fig-p\">#### B. Silent Communication State (<code>COMM_SILENT_COMMUNICATION</code>)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>ComM</code> ruft synchron <code>Dcm_ComM_SilentComModeEntered(uint8 NetworkId)</code> auf.</li>\n<li><strong>Aktionen im Dcm:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Deaktivierung der Transmission für ROE und Periodic-IDs.</li>\n<li>Selektives Sperren der Sendepfade: Regulärer Empfang (<code>Rx</code>) bleibt aktiv (ECU hört passiv mit), jegliche aktive Aussendung (<code>Tx</code> via <code>PduR_DcmTransmit()</code>) wird unterdrückt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Synchroner Rücksprung (<code>Dcm_ComMSilentComModeEntered()</code>) an <code>ComM</code>.</li>\n</ol>\n<p class=\"fig-p\">#### C. Full Communication State (<code>COMM_FULL_COMMUNICATION</code>)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>ComM</code> ruft synchron <code>Dcm_ComM_FullComModeEntered(uint8 NetworkId)</code> auf.</li>\n<li><strong>Aktionen im Dcm:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Reaktivierung/Freigabe der Transmission für ROE und Periodic-IDs.</li>\n<li>Vollständige Freigabe der normalen Diagnose-Kommunikation (<code>Rx</code> und <code>Tx</code> via <code>PduR_DcmTransmit()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Synchroner Rücksprung (<code>Dcm_ComMFullComModeEntered()</code>) an <code>ComM</code>.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Kanal-Granularität (<code>NetworkId</code>):</strong> Die Umschaltung erfolgt kanalbezogen (<code>uint8</code>). Bei Multi-Channel-/Gateway-ECUs muss der Dcm interne Puffer und Zustandsflags pro Kanal isoliert verwalten.</li>\n<li><strong>PduR-Entkopplung:</strong> Sobald <code>SilentCom</code> oder <code>NoCom</code> gemeldet wird, darf der Dcm unter keinen Umständen <code>PduR_DcmTransmit()</code> aufrufen. Anstehende TX-Bestätigungen oder ausstehende Antworten sind konform zu verwerfen bzw. zu blockieren, um Bus-Wakeup-Verletzungen zu verhindern.</li>\n<li><strong>Listen-Only im Silent-Modus:</strong> Der Empfangspfad bleibt in <code>SilentCom</code> aktiv. Diagnoserequests werden gepuffert oder intern verarbeitet, dürfen aber keine physische Antwort auf dem Bus erzeugen.</li>\n<li><strong>Asynchrone Services (ROE / 0x2A):</strong> Der Dcm muss den Zustand (aktiviert/konfiguriert) von ROE und periodischen Identifiers intern sichern; bei Eintritt in <code>FullCom</code> werden nur jene Transmissionen reaktiviert, die zuvor bereits aktiv waren (kein unkontrollierter Neustart inaktiver Events).</li>\n</ul>"}, {"id": "FIG-9b81b467e2bf9051", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsübersicht mit drei isolierten Zustandswechsel-Szenarien).</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert die BSW-Interaktion auf System-Service-Ebene zwischen dem Communication Manager (<code>ComM</code>) und dem Diagnostic Communication Manager (<code>Dcm</code>) gemäß AUTOSAR Classic Platform (SWS DCM, Release R24-11).</li>\n<li><strong>Technischer Zweck:</strong> Kanalbezogene Steuerung der diagnostischen Sende- und Empfangsbereitschaft des Dcm (Diagnostic Session Layer / DSL) in Abhängigkeit vom Netzwerkmodus des jeweiligen Kommunikationskanals (Verhinderung unzulässiger Buslast oder unerwünschten Bus-Wakeups).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Module (Akteure):</strong></li>\n<li><code>«module» ComM</code>: Koordinator der Buskommunikationszustände (Network Management / State Machine).</li>\n<li><code>«module» Dcm</code>: Protokoll- und Session-Handler für UDS/OBD-Diagnose.</li>\n<li><strong>Dcm Mode-Notification APIs (Aufruf durch ComM):</strong></li>\n<li><code>Dcm_ComM_NoComModeEntered(uint8 NetworkId)</code>: Signalisiert Kanal-Übergang zu <code>COMM_NO_COMMUNICATION</code>.</li>\n<li><code>Dcm_ComM_SilentComModeEntered(uint8 NetworkId)</code>: Signalisiert Kanal-Übergang zu <code>COMM_SILENT_COMMUNICATION</code>.</li>\n<li><code>Dcm_ComM_FullComModeEntered(uint8 NetworkId)</code>: Signalisiert Kanal-Übergang zu <code>COMM_FULL_COMMUNICATION</code>.</li>\n<li><strong>Interne / Unterlagerte Schnittstellen:</strong></li>\n<li><code>PduR_DcmTransmit()</code>: PDU-Router-Schnittstelle zur Übertragung diagnostischer Antworten.</li>\n<li>ROE-Handler (UDS 0x86 <em>ResponseOnEvent</em>) und Periodic-ID-Handler (UDS 0x2A <em>ReadDataByPeriodicIdentifier</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. No Communication State (<code>COMM_NO_COMMUNICATION</code>)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>ComM</code> ruft synchron <code>Dcm_ComM_NoComModeEntered(uint8 NetworkId)</code> auf.</li>\n<li><strong>Aktionen im Dcm:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Deaktivierung der Transmission für ROE und Periodic-IDs auf dem betroffenen Netzwerk.</li>\n<li>Vollständiges Sperren der normalen Diagnose-Kommunikation: Empfang (<code>Rx</code>) und Senden (<code>Tx</code> via <code>PduR_DcmTransmit()</code>) werden unterbunden.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Synchroner Rücksprung (<code>Dcm_ComMNoComModeEntered()</code>) an <code>ComM</code>.</li>\n</ol>\n<p class=\"fig-p\">#### B. Silent Communication State (<code>COMM_SILENT_COMMUNICATION</code>)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>ComM</code> ruft synchron <code>Dcm_ComM_SilentComModeEntered(uint8 NetworkId)</code> auf.</li>\n<li><strong>Aktionen im Dcm:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Deaktivierung der Transmission für ROE und Periodic-IDs.</li>\n<li>Selektives Sperren der Sendepfade: Regulärer Empfang (<code>Rx</code>) bleibt aktiv (ECU hört passiv mit), jegliche aktive Aussendung (<code>Tx</code> via <code>PduR_DcmTransmit()</code>) wird unterdrückt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Synchroner Rücksprung (<code>Dcm_ComMSilentComModeEntered()</code>) an <code>ComM</code>.</li>\n</ol>\n<p class=\"fig-p\">#### C. Full Communication State (<code>COMM_FULL_COMMUNICATION</code>)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>ComM</code> ruft synchron <code>Dcm_ComM_FullComModeEntered(uint8 NetworkId)</code> auf.</li>\n<li><strong>Aktionen im Dcm:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Reaktivierung/Freigabe der Transmission für ROE und Periodic-IDs.</li>\n<li>Vollständige Freigabe der normalen Diagnose-Kommunikation (<code>Rx</code> und <code>Tx</code> via <code>PduR_DcmTransmit()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Synchroner Rücksprung (<code>Dcm_ComMFullComModeEntered()</code>) an <code>ComM</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Kanal-Granularität (<code>NetworkId</code>):</strong> Die Umschaltung erfolgt kanalbezogen (<code>uint8</code>). Bei Multi-Channel-/Gateway-ECUs muss der Dcm interne Puffer und Zustandsflags pro Kanal isoliert verwalten.</li>\n<li><strong>PduR-Entkopplung:</strong> Sobald <code>SilentCom</code> oder <code>NoCom</code> gemeldet wird, darf der Dcm unter keinen Umständen <code>PduR_DcmTransmit()</code> aufrufen. Anstehende TX-Bestätigungen oder ausstehende Antworten sind konform zu verwerfen bzw. zu blockieren, um Bus-Wakeup-Verletzungen zu verhindern.</li>\n<li><strong>Listen-Only im Silent-Modus:</strong> Der Empfangspfad bleibt in <code>SilentCom</code> aktiv. Diagnoserequests werden gepuffert oder intern verarbeitet, dürfen aber keine physische Antwort auf dem Bus erzeugen.</li>\n<li><strong>Asynchrone Services (ROE / 0x2A):</strong> Der Dcm muss den Zustand (aktiviert/konfiguriert) von ROE und periodischen Identifiers intern sichern; bei Eintritt in <code>FullCom</code> werden nur jene Transmissionen reaktiviert, die zuvor bereits aktiv waren (kein unkontrollierter Neustart inaktiver Events).</li>\n</ul>"}], "trans": [{"from": "FIG-a4ee3b1d3977bf8a", "to": "FIG-9b81b467e2bf9051", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
